class Student {
    String name;
    int age;
    String course;

    void display() {
        System.out.println(name + " | " + age + " yrs | Course: " + course);
    }
}

public class Main {
    public static void main(String[] args) {
        // Student 1
        Student s1 = new Student();
        s1.name = "Rahul";
        s1.age = 20;
        s1.course = "Java";

        // Student 2
        Student s2 = new Student();
        s2.name = "Priya";
        s2.age = 21;
        s2.course = "Python";

        // Student 3
        Student s3 = new Student();
        s3.name = "Arjun";
        s3.age = 19;
        s3.course = "Web Dev";

        // Printing each independently:
        s1.display();
        s2.display();
        s3.display();
    }
}

