class Book {
    String title;
    String author;
}

public class Main {
    public static void main(String[] args) {
        Book b1 = new Book();
        b1.title = "Atomic Habits";
        b1.author = "James Clear";

        Book b2 = new Book();
        b2.title = "Clean Code";
        b2.author = "Robert Martin";

        Book b3 = new Book();
        b3.title = "Java Basics";
        b3.author = "LearnBySelf";

        System.out.println(b1.title + " by " + b1.author);
        System.out.println(b2.title + " by " + b2.author);
        System.out.println(b3.title + " by " + b3.author);
    }
}

class Rectangle {
    int length;
    int width;

    void printArea() {
        System.out.println("Area: " + (length * width));
    }
}

public class Main {
    public static void main(String[] args) {
        Rectangle r1 = new Rectangle();
        r1.length = 5;
        r1.width = 4;

        Rectangle r2 = new Rectangle();
        r2.length = 10;
        r2.width = 3;

        r1.printArea();
        r2.printArea();
    }
}
